import React, { useState, useEffect, useMemo } from 'react';
import axios from 'axios';
import { Col, Row, Label } from 'reactstrap';
import ColorPicker from './components/ColorPicker';
import CustomInput from '../Common/CustomInput';
import CustomCheckbox from './components/CustomCheckbox';
import CommonSelect from './components/CommonSelect';
import {
  formEmpSelectList,
  formResMessage,
  formStudentSelectList,
  getGlobalCurrentBatchUtils,
  getGlobalSchoolUtils,
  infoIconSm,
  makeSubText,
} from 'utils/commonFunc';
import constants, { employeeStatic, formStudentName, makeFirstCaps } from 'config/constants';
import CustomButton from 'components/CustomButton';
import AwardCard from './components/AwardCard';
import { useHistory, useLocation } from 'react-router-dom';
import { useSelector, useDispatch } from 'react-redux';
import {
  addOrUpdateAppreciationTemplateService,
  fetchAppreciationCardService,
  fetchAppreciationTemplateService,
  saveAppreciationAsDraftService,
  searchSchoolStudentsService,
  sendAppreciationCardService,
  // assignAppreciationTemplateService,
  // fetchAllAppreciationTemplatesService,
  // fetchAllAppreciationAssignsService,
} from 'actions/admin/schools';
import CommonTooltip from '../Common/CommonTooltip';
import { fetchSchoolEmployeesApi } from 'actions/admin/employees';
import { showToast } from 'actions/admin/auth';
import DatePicker from 'views/admin/Common/Datepicker';
import moment from 'moment';

export const fontFamilies = [
  { label: 'Times New Roman', value: 'Times New Roman, serif' },
  { label: 'Arial', value: 'Arial, sans-serif' },
  { label: 'Helvetica', value: 'Helvetica, sans-serif' },
  { label: 'Verdana', value: 'Verdana, sans-serif' },
  { label: 'Trebuchet MS', value: 'Trebuchet MS, sans-serif' },
  { label: 'Arial Black', value: 'Arial Black, sans-serif' },
  { label: 'Impact', value: 'Impact, sans-serif' },
  { label: 'Palatino', value: 'Palatino, serif' },
  { label: 'Garamond', value: 'Garamond, serif' },
  { label: 'Bookman', value: 'Bookman, serif' },
  { label: 'Comic Sans MS', value: 'Comic Sans MS, cursive' },
  { label: 'Lucida Console', value: 'Lucida Console, monospace' },
  { label: 'Courier New', value: 'Courier New, monospace' },
  { label: 'Courier', value: 'Courier, monospace' },
  { label: 'Georgia', value: 'Georgia, serif' },
];

export const fontWeights = [
  { label: 'Normal', value: 'normal' },
  { label: 'Bold', value: 'bold' },
  { label: 'Bolder', value: 'bolder' },
];

const templateForOptions = [
  { label: 'Student', value: 'STUDENT' },
  { label: employeeStatic, value: employeeStatic },
  // { label: 'Admin', value: 'ADMIN' },
  // { label: 'Other', value: 'OTHER' },
];

const globalSchool = getGlobalSchoolUtils();

export const initialAppreciationState = {
  headerIcon: {
    label: 'Header Logo',
    fieldValue: 'fas fa-award',
    style: { fontSize: 35, color: '#007bff' },
  },
  certificateStyle: {
    fontFamily: 'Arial, sans-serif',
    color: '#000000',
    backgroundColor: '#ffffff',
    borderColor: '#FFA500',
    borderWidth: 4,
    isCaps: false,
  },
  schoolName: {
    type: 'INPUT',
    label: 'School Or Institute Name',
    fieldValue: globalSchool?.schoolName,
    style: { fontSize: 17, color: '#ababab', fontFamily: 'Arial, sans-serif', fontWeight: 'bold', isCaps: false },
  },
  certificationName: {
    type: 'INPUT',
    label: 'Certification Name',
    fieldValue: 'Best Performer Award',
    style: { fontSize: 20, color: '#000000', fontFamily: 'Times New Roman, serif', fontWeight: 'bolder', isCaps: true },
  },
  description: {
    type: 'TEXT_AREA',
    label: 'Description',
    fieldValue:
      'has successfully completed all the requirements for graduation prescribed by the Department of Education.',
    style: { fontSize: 14, color: '#000000', fontFamily: 'Arial, sans-serif', fontWeight: 'normal', isCaps: false },
  },
  activityDate: {
    type: 'MONTH_PICKER',
    label: 'Activity month',
    fieldValue: moment().format('YYYY-MM-DD'),
    style: { fontSize: 14, color: '#000000', fontFamily: 'Arial, sans-serif', fontWeight: 'bolder', isCaps: false },
  },
  // From
  fromUser: {
    label: 'By',
    fieldValue: 'Provider name here',
    style: { fontSize: 14, color: '#000000', fontFamily: 'Arial, sans-serif', fontWeight: 'bolder', isCaps: false },
  },
  fromUserDesignation: {
    label: 'Designation',
    fieldValue: 'Principal',
    style: { fontSize: 13, color: '#000000', fontFamily: 'Arial, sans-serif', fontWeight: 'normal', isCaps: false },
  },
  fromUserRole: '',
  fromUserId: 0,
  // To
  toUser: {
    label: 'To',
    fieldValue: 'Student name here',
    style: { fontSize: 15, color: '#007bff', fontFamily: 'Arial, sans-serif', fontWeight: 'bold', isCaps: false },
  },
  toUserRole: '',
  toUserId: 0,
  toUserDesignation: '',
  status: '',
  toWhom: 'STUDENT',
};

let searchTimer;
const AppreciationTemplate = () => {
  const authStore = useSelector(state => state?.auth);
  const { loggedUserToken, loggedUserId, loggedUserRole } = authStore;
  const schoolStore = useSelector(state => state?.schools);
  const dispatch = useDispatch();
  const location = useLocation();
  const history = useHistory();
  const [selectedField, setSelectedField] = useState('');
  const [activeField, setActiveField] = useState('');
  const [appreciation, setAppreciation] = useState(initialAppreciationState);
  const [isSaving, setLoading] = useState(false);
  // const [searchText, setSearchText] = useState('');
  const [stateStudents, setStateStudents] = useState([]);
  const [stateEmployees, setStateEmployees] = useState([]);
  const [isDraftSaving, setDraftSaveLoading] = useState(false);
  const [appreciationCard, setAppreciationCard] = useState({});
  const [isSendSaving, setSendSaveLoading] = useState(false);
  // Who a sent / drafted card is for (the card stores only the id), for the view and print page.
  const [recipientName, setRecipientName] = useState('');

  const query = new URLSearchParams(location?.search);
  const action = query.get('action');
  const onlyPrint = ['noaction', 'sent', 'SENT'].includes(action);
  const isDrafted = ['draft', 'DRAFT'].includes(action);
  const appreTemplateId = query.get('appreTemplateId');
  const appreciationId = query.get('appreciationId');

  const { certificateStyle, headerIcon, toWhom, toUserId } = appreciation;
  const { fontFamily: certFontFamily, borderWidth: certBorderWidth } = certificateStyle;
  const { status } = appreciationCard;

  const navBackToAppreciations = () => {
    history.push('/admin/appreciations');
  };

  const fetchSchoolEmployees = async () => {
    const globalSchool = getGlobalSchoolUtils();
    const employees = await fetchSchoolEmployeesApi({
      token: loggedUserToken,
      schoolId: globalSchool?.schoolId,
      profession: 'TEACHING',
    });
    const empList = formEmpSelectList(employees);
    setStateEmployees(empList);
  };

  const fetchSclEmpOrStudents = () => {
    if ([toWhom, schoolStore?.appreciation?.toWhom].includes(employeeStatic)) {
      fetchSchoolEmployees();
    }
  };

  useEffect(() => {
    fetchSclEmpOrStudents();
  }, [toWhom, action]);

  useEffect(() => {
    if (action === 'assign') {
      setSelectedField('toUser');
    }
  }, [action]);

  const fetchAppreciationTemplate = async () => {
    try {
      const res = await fetchAppreciationTemplateService({
        dispatch,
        token: loggedUserToken,
        appreTemplateId,
      });
      !res?.appreTemplateId && navBackToAppreciations();
    } catch (err) {
      navBackToAppreciations();
    }
  };

  useEffect(() => {
    if (schoolStore?.appreciation?.appreTemplateId) {
      const formFields =
        schoolStore?.appreciation?.templateJson && typeof schoolStore?.appreciation?.templateJson === 'string'
          ? JSON.parse(schoolStore?.appreciation?.templateJson)
          : typeof schoolStore?.appreciation?.templateJson === 'object'
          ? schoolStore?.appreciation?.templateJson
          : {};
      setAppreciation({
        appreTemplateId: schoolStore?.appreciation?.appreTemplateId,
        schoolId: schoolStore?.appreciation?.schoolId,
        ...{ ...formFields, appreTemplateId: schoolStore?.appreciation?.appreTemplateId },
        toWhom: schoolStore?.appreciation?.toWhom,
      });
    } else if (appreTemplateId) {
      fetchAppreciationTemplate();
    } else if (action !== 'create') {
      navBackToAppreciations();
    }
  }, [action, location?.search, schoolStore?.appreciation?.appreTemplateId, appreTemplateId]);

  const replaceSearchParams = passSearchParams => {
    history.replace({
      pathname: location.pathname,
      search: passSearchParams,
    });
  };

  const fetchAppreciationCard = async passAppreciationId => {
    if (!appreciationCard?.appreciationId) {
      try {
        const res = await fetchAppreciationCardService({
          dispatch,
          token: loggedUserToken,
          appreciationId: passAppreciationId || appreciationId,
        });
        if (res.appreciationId) setAppreciationCard(res);
      } catch (err) {
        console.error('fetchAppreciationCardService', err);
      }
    }
  };

  useEffect(() => {
    if (appreciationId) {
      fetchAppreciationCard();
    }
  }, [action, location?.search, schoolStore?.appreciation?.appreTemplateId, appreciationId]);

  useEffect(() => {
    const id = appreciationCard?.toUserId;
    if (!id) {
      return;
    }
    const isStudent = appreciationCard.toUserRole === 'ROLE_STUDENT';
    const url = isStudent
      ? `${constants.API_BASE_URL}/api/student/${id}/${appreciationCard.batchId}`
      : `${constants.API_BASE_URL}/api/employee/get-employee/${id}`;
    axios
      .get(url, constants.setHeader(loggedUserToken))
      .then(res => setRecipientName(isStudent ? formStudentName(res.data) : res.data?.name || ''))
      .catch(() => setRecipientName(''));
  }, [appreciationCard?.toUserId, appreciationCard?.toUserRole, appreciationCard?.batchId, loggedUserToken]);

  // The view / print page shows the card as it was sent: the template's look with the card's own heading, text and date.
  // (Without this it showed the template's sample text, whatever was written for the person.)
  const shownAppreciation = useMemo(() => {
    if (!(onlyPrint || isDrafted) || !appreciationCard?.appreciationId) {
      return appreciation;
    }
    return {
      ...appreciation,
      certificationName: {
        ...appreciation.certificationName,
        fieldValue: appreciationCard.heading || appreciation.certificationName?.fieldValue,
      },
      description: {
        ...appreciation.description,
        fieldValue: appreciationCard.description || appreciation.description?.fieldValue,
      },
      activityDate: {
        ...appreciation.activityDate,
        fieldValue: appreciationCard.activityDate || appreciation.activityDate?.fieldValue,
      },
    };
  }, [appreciation, appreciationCard, onlyPrint, isDrafted]);

  const handleSaveAppreciationTemplate = async () => {
    const globalSchool = getGlobalSchoolUtils();
    try {
      setLoading(true);
      await addOrUpdateAppreciationTemplateService({
        appreciation,
        action,
        token: loggedUserToken,
        schoolId: globalSchool?.schoolId,
      });
      setLoading(false);
      navBackToAppreciations();
    } catch (err) {
      setLoading(false);
    }
  };

  const formAppreciaionCard = (passAppreciationId = 0) => {
    const batch = getGlobalCurrentBatchUtils();
    return {
      activityDate: appreciationCard?.activityDate || appreciation?.activityDate?.fieldValue,
      appreciationId: passAppreciationId || appreciationId || 0,
      batchId: appreciationCard?.batchId || batch?.batchId,
      description: appreciationCard?.description || appreciation.description.fieldValue,
      fromUserId: loggedUserId,
      fromUserRole: loggedUserRole,
      heading: appreciation?.certificationName?.fieldValue || 'NO_HEADING',
      schoolId: globalSchool.schoolId,
      status: ['DRAFT', 'PENDING'].includes(status) ? 'SENT' : 'DRAFT',
      templateId: Number(appreTemplateId || 0),
      templateType: 'NO_URL',
      toUserId: appreciationCard?.toUserId || appreciation.toUserId,
      toUserRole: toWhom === 'STUDENT' ? 'ROLE_STUDENT' : 'ROLE_TEACHER',
    };
  };

  const handleSaveAsDraft = async (actionObj = {}) => {
    const { sendAction = '' } = actionObj;
    if (appreciationCard?.toUserId || appreciation?.toUserId) {
      const batch = getGlobalCurrentBatchUtils();
      const globalSchool = getGlobalSchoolUtils();
      if (sendAction !== 'from_save_and_send') setDraftSaveLoading(true);
      try {
        const res = await saveAppreciationAsDraftService({
          appreciationCard: formAppreciaionCard(),
          batchId: batch?.batchId,
          schoolId: globalSchool.schoolId,
          token: loggedUserToken,
        });
        setDraftSaveLoading(false);
        if (res?.appreciationId) {
          if (!appreciationCard?.appreciationId) {
            fetchAppreciationCard(res?.appreciationId);
          }
          replaceSearchParams(`${location?.search}&appreciationId=${res.appreciationId}`);
        }
        return res;
      } catch (err) {
        setDraftSaveLoading(false);
        dispatch(showToast(formResMessage(err), 'error'));
      }
    } else {
      dispatch(showToast('Select User to Save Or Send Appreciation Card', 'warning'));
    }
  };

  const handleSendAppreciation = async (actionObj = {}) => {
    const { sendAction = 'direct', appreciationId = 0 } = actionObj;
    if (appreciationCard?.toUserId || appreciation?.toUserId) {
      const batch = getGlobalCurrentBatchUtils();
      const globalSchool = getGlobalSchoolUtils();
      setSendSaveLoading(true);
      try {
        const res = await sendAppreciationCardService({
          appreciationCard: formAppreciaionCard(appreciationId),
          batchId: batch?.batchId,
          schoolId: globalSchool.schoolId,
          token: loggedUserToken,
        });
        setSendSaveLoading(false);
        if (res?.appreciationId) {
          replaceSearchParams(`${location?.search}&appreciationId=${res.appreciationId}`);
        }
        if (sendAction === 'direct') {
          navBackToAppreciations();
        } else {
          return res;
        }
      } catch (err) {
        console.error('err', err);
        setSendSaveLoading(false);
        dispatch(showToast(formResMessage(err), 'error'));
      }
    }
  };

  const handleSaveAndSend = async () => {
    const res = await handleSaveAsDraft({ sendAction: 'from_save_and_send' });
    if (res?.appreciationId) {
      await handleSendAppreciation({ sendAction: 'direct', appreciationId: res?.appreciationId });
    }
  };

  const handleTemplateForChange = (name, selected) => {
    setAppreciation(prevState => ({
      ...prevState,
      [name]: selected,
      toUser: {
        ...prevState?.toUser,
        fieldValue: `${makeFirstCaps(selected)} name here`,
      },
    }));
  };

  const handleFielStyleChange = (fieldName, name, value) => {
    setAppreciation(prevState => ({
      ...prevState,
      [fieldName]: {
        ...prevState?.[fieldName],
        style: {
          ...prevState?.[fieldName]?.style,
          [name]: value,
        },
      },
    }));
  };

  const handleFieldValueChange = (name, value) => {
    setAppreciation(prevState => ({
      ...prevState,
      [name]: {
        ...prevState?.[name],
        fieldValue: value,
      },
    }));
  };

  const handleChange = (name, value) => {
    setAppreciation(prevState => ({
      ...prevState,
      [name]: value,
    }));
  };

  const handleCardParamChange = (name, value) => {
    if ((name === 'borderWidth' && Number(value) >= 4) || name !== 'borderWidth') {
      handleChange('certificateStyle', { ...certificateStyle, [name]: value });
    }
  };

  const handleSetActiveField = fieldName => action !== 'assign' && fieldName && setActiveField(fieldName);

  const handleSelectItem = fieldName => {
    action !== 'assign' && fieldName && setSelectedField(fieldName);
    // setFocusActiveField(fieldName);
  };

  const searchStudents = async passText => {
    // setSearchText(passText);
    const globalSchool = getGlobalSchoolUtils();
    const batch = getGlobalCurrentBatchUtils();
    clearTimeout(searchTimer);
    searchTimer = setTimeout(async () => {
      const students = await searchSchoolStudentsService({
        token: loggedUserToken,
        schoolId: globalSchool?.schoolId,
        searchKeyWord: passText,
        batchId: batch?.batchId,
      });
      if (Array.isArray(students) && students?.length) {
        const stList = formStudentSelectList(students);
        setStateStudents(stList);
      }
    }, 300);
  };

  const getStudent = id => {
    return stateStudents?.find(el => el.studentId === id);
  };

  const getEmployee = id => {
    return stateEmployees?.find(el => el.employeeId === id);
  };

  const handleUserChange = userId => {
    let stateAppreciation = appreciation;
    const user = toWhom === 'STUDENT' ? getStudent(userId) : getEmployee(userId);
    if (user) {
      stateAppreciation = {
        ...stateAppreciation,
        toUser: {
          ...stateAppreciation.toUser,
          fieldValue: toWhom === 'STUDENT' ? formStudentName(user) : user?.name,
        },
        toUserRole: `ROLE_${toWhom !== 'STUDENT' ? 'TEACHER' : toWhom}`,
        toUserId: userId,
        toUserDesignation: user?.designation || '',
      };
    }
    setAppreciation(stateAppreciation);
  };

  const getButtonLabel = () => {
    const buttonLabelData = {
      view: 'Update Template',
      create: 'Create Template',
    };
    return buttonLabelData?.[action];
  };

  const isFieldUser = selectedField => {
    return selectedField === 'toUser' && ['STUDENT', employeeStatic?.toUpperCase()].includes(toWhom?.toUpperCase());
  };

  const showInfoIcon = selectedField => {
    const isShowIcon =
      selectedField === 'toUser' && ['STUDENT', employeeStatic?.toUpperCase()].includes(toWhom?.toUpperCase());
    return (
      isShowIcon &&
      action !== 'assign' && (
        <sup>
          <CommonTooltip content="Since its a template, you can only modify the styles. Name can only modified while assign">
            <span className="ml-2">{infoIconSm()}</span>
          </CommonTooltip>
        </sup>
      )
    );
  };

  const getOptions = () => {
    return toWhom === 'STUDENT' ? stateStudents : stateEmployees;
  };

  const isAssign = action === 'assign';
  const getColumsForSelected = formField => {
    const optionList = getOptions();
    const stateField = appreciation?.[formField];
    const isHeaderIcon = stateField === headerIcon;
    return (
      <div className="p-3">
        <Row>
          <Col md={12}>
            {isFieldUser(formField) && action === 'assign' ? (
              <div className="mt-0 mb-3">
                <CommonSelect
                  name="toUserId"
                  noLabel={true}
                  value={toUserId || appreciationCard?.toUserId}
                  onChange={(name, value) => {
                    handleUserChange(value);
                  }}
                  options={optionList}
                  disabled={isHeaderIcon || appreciationCard?.toUserId || onlyPrint || isDrafted}
                  onInputChange={text => {
                    toWhom === 'STUDENT' && searchStudents(text);
                  }}
                  applyLabelStyle={true}
                />
              </div>
            ) : stateField?.type === 'MONTH_PICKER' ? (
              <DatePicker
                className="mt-0 mb-2"
                handleDateChange={date => handleFieldValueChange(formField, moment(date).format('YYYY-MM-DD'))}
                selectedDate={stateField?.fieldValue}
                disabled={isHeaderIcon || isFieldUser(formField) || onlyPrint || isDrafted}
                showOnlyMonthAndYear
              />
            ) : (
              <CustomInput
                type={stateField?.type === 'TEXT_AREA' ? 'textarea' : 'text'}
                name="fieldValue"
                onChange={(name, value) => handleFieldValueChange(formField, value)}
                value={stateField?.fieldValue}
                rows="5"
                disabled={isHeaderIcon || isFieldUser(formField) || onlyPrint || isDrafted}
              />
            )}
          </Col>
        </Row>
        <Row>
          <Col md={4}>
            <CustomInput
              label={makeSubText('Font size', { noBracket: true })}
              type="number"
              name="fontSize"
              onChange={(name, value) => handleFielStyleChange(formField, name, value)}
              value={stateField?.style?.fontSize}
              disabled={isAssign || onlyPrint || isDrafted}
            />
          </Col>
          <Col md={8}>
            <CommonSelect
              label={makeSubText('Font family', { noBracket: true })}
              name="fontFamily"
              value={stateField?.style?.fontFamily}
              onChange={(name, selected) => handleFielStyleChange(formField, 'fontFamily', selected)}
              options={fontFamilies}
              disabled={isHeaderIcon || isAssign || onlyPrint || isDrafted}
            />
          </Col>
        </Row>
        {/* Row */}
        <Row>
          <Col md={4}>
            <ColorPicker
              label={makeSubText('Color', { noBracket: true })}
              name="color"
              handleColorChange={(name, value) => handleFielStyleChange(formField, name, value)}
              value={stateField?.style?.color}
              disabled={isAssign || onlyPrint || isDrafted}
            />
          </Col>
          <Col md={8}>
            <CommonSelect
              label={makeSubText('Font weight', { noBracket: true })}
              name="fontWeight"
              value={stateField?.style?.fontWeight}
              onChange={(name, selected) => handleFielStyleChange(formField, 'fontWeight', selected)}
              options={fontWeights}
              disabled={isHeaderIcon || isAssign || onlyPrint || isDrafted}
            />
          </Col>
        </Row>
        {/* Row */}
        <Row className="mt-2">
          <Col md={4}>
            <Label>{makeSubText('Is Caps', { noBracket: true })}</Label>
            <CustomCheckbox
              label={stateField?.style?.isCaps ? 'CAPS' : 'SMALL'}
              name="isCaps"
              onChange={(name, value) => handleFielStyleChange(formField, name, value)}
              value={stateField?.style?.isCaps}
              checked={stateField?.style?.isCaps}
              disabled={isHeaderIcon || isAssign || onlyPrint || isDrafted}
            />
          </Col>
        </Row>
      </div>
    );
  };

  return (
    <div className="content">
      <Row
        style={{
          marginLeft: 10,
        }}>
        <Col md={4}>
          <CommonSelect
            label={makeSubText('Appreciation Template For', { noBracket: true })}
            name="toWhom"
            value={toWhom}
            onChange={(name, selected) => handleTemplateForChange(name, selected)}
            options={templateForOptions}
            disabled={action === 'assign' || onlyPrint || isDrafted}
            placeholder="Search..."
          />
        </Col>
        <Col md={8}>
          <span style={{ float: 'right' }}>
            {onlyPrint ? (
              <CustomButton
                className="ml-1"
                variant="outlined"
                name="Print"
                onClick={() => {
                  // setActiveField('');
                  // setSelectedField('');
                  window.print();
                }}
              />
            ) : ['create', 'view'].includes(action) ? (
              <CustomButton
                className="ml-1"
                name={getButtonLabel()}
                onClick={() => {
                  handleSaveAppreciationTemplate();
                }}
                disabled={isSaving || onlyPrint || isDrafted}
                loading={isSaving}
                showLoader={true}
              />
            ) : (
              <>
                {!appreciationId ? (
                  <CustomButton
                    variant="outlined"
                    className="ml-1"
                    name="Save as Draft"
                    onClick={() => {
                      handleSaveAsDraft();
                    }}
                    disabled={isDraftSaving || isSendSaving || onlyPrint || isDrafted}
                    loading={isDraftSaving}
                    showLoader={true}
                  />
                ) : appreciationId && status === 'DRAFT' ? (
                  <CustomButton
                    className="ml-1"
                    name="Send"
                    onClick={() => {
                      handleSendAppreciation({ sendAction: 'direct' });
                    }}
                    disabled={isSaving || isDraftSaving || isSendSaving || onlyPrint}
                    loading={isSendSaving}
                    showLoader={true}
                  />
                ) : null}
                {!appreciationId && (
                  <CustomButton
                    className="ml-1"
                    name="Save & Send"
                    onClick={() => {
                      handleSaveAndSend();
                    }}
                    disabled={isDraftSaving || isSendSaving || onlyPrint}
                    loading={isSendSaving}
                    showLoader={true}
                  />
                )}
              </>
            )}
            <CustomButton
              color="default"
              className="ml-1"
              name="Go back"
              onClick={() => navBackToAppreciations()}
              disabled={isSaving || isDraftSaving || isSendSaving}
            />
          </span>
        </Col>
      </Row>
      <Row>
        <Col md={8}>
          <AwardCard
            onlyPrint={onlyPrint || ['draft', 'DRAFT'].includes(status)}
            appreciation={shownAppreciation}
            selectedField={selectedField}
            activeField={activeField}
            setActiveField={handleSetActiveField}
            handleSelectItem={handleSelectItem}
            isAssigned={!!appreciationId || ['draft', 'DRAFT'].includes(status)}
            toUserName={recipientName || getOptions()?.find(el => el.value === appreciationCard.toUserId)?.name}
          />
        </Col>
        <Col md={4}>
          <form>
            <div style={{ padding: '20px 15px 20px 15px', backgroundColor: '#ffffff' }}>
              <Row className="mb-3">
                {[
                  { label: 'Background', value: 'backgroundColor' },
                  { label: 'Border', value: 'borderColor' },
                  { label: 'Font', value: 'color' },
                ].map((el, index) => {
                  return (
                    <Col key={index} md={4}>
                      <ColorPicker
                        label={makeSubText(el.label, { noBracket: true })}
                        name={el.value}
                        handleColorChange={handleCardParamChange}
                        value={certificateStyle?.[el?.value]}
                        disabled={isAssign || onlyPrint || isDrafted}
                      />
                    </Col>
                  );
                })}
              </Row>
              <Row>
                <Col md={4}>
                  <CustomInput
                    label={makeSubText('Border size', { noBracket: true })}
                    type="number"
                    name="borderWidth"
                    onChange={handleCardParamChange}
                    value={certBorderWidth}
                    disabled={isAssign || onlyPrint || isDrafted}
                  />
                </Col>
                <Col md={8}>
                  <CommonSelect
                    label={makeSubText('Font family', { noBracket: true })}
                    name="fontFamily"
                    value={certFontFamily}
                    onChange={handleCardParamChange}
                    options={fontFamilies}
                    disabled={isAssign || onlyPrint || isDrafted}
                  />
                </Col>
              </Row>
            </div>
            {selectedField && (
              <div style={{ marginTop: 15, padding: '10px 5px 10px 5px', backgroundColor: '#ffffff' }}>
                <span className="ml-3">
                  {makeSubText(appreciation?.[selectedField]?.label || 'Designation', {
                    noBracket: true,
                    fontSize: 15,
                  })}
                </span>
                {showInfoIcon(selectedField)}
                {getColumsForSelected(selectedField)}
              </div>
            )}
          </form>
        </Col>
      </Row>
    </div>
  );
};

export default AppreciationTemplate;
