import React from 'react';
import { CustomInput } from 'reactstrap';

function CustomCheckbox({ label, name, value, checked, onChange, disabled }) {
  return (
    <CustomInput
      type="checkbox"
      id={name}
      name={name}
      label={label}
      value={value}
      checked={checked}
      onChange={e => {
        onChange(name, e.target.checked);
      }}
      onClick={e => {
        onChange(name, e.target.checked);
      }}
      disabled={disabled}
    />
  );
}

export default CustomCheckbox;
