import React, { useRef } from 'react';
import { Card, CardContent, makeStyles } from '@material-ui/core';
import moment from 'moment';

const useStyles = makeStyles({
  root: {
    minWidth: 275,
    borderRadius: 0,
    margin: 30,
  },
  bullet: {
    display: 'inline-block',
    margin: '0 2px',
    transform: 'scale(0.8)',
  },
  title: {
    fontSize: 14,
  },
  pos: {
    marginBottom: 12,
  },
});

const activeBorder = '1px solid #007bff';

const AwardCard = ({
  transform,
  appreciation,
  selectedField,
  activeField,
  setActiveField,
  handleSelectItem,
  isAssigned,
  toUserName,
  onlyPrint,
}) => {
  const classes = useStyles();
  const wrapperRef = useRef(null);
  const {
    certificateStyle,
    headerIcon,
    schoolName,
    certificationName,
    toUser,
    description,
    activityDate,
    fromUser,
    fromUserDesignation,
    // toWhom,
  } = appreciation;
  const {
    fontFamily,
    backgroundColor,
    borderColor,
    borderWidth,
    color,
    //isCaps
  } = certificateStyle;

  const setActiveFieldChange = (key = '') => {
    !onlyPrint && setActiveField?.(key);
  };

  const handleSelectItemChange = (key = '') => {
    !onlyPrint && handleSelectItem?.(key);
  };

  return (
    <Card id="print-section" className={classes.root} ref={wrapperRef} style={{ transform }}>
      <CardContent
        style={{
          margin: 30,
          paddingLeft: 40,
          paddingRight: 40,
          border: `${borderWidth}px solid ${borderColor}`,
          backgroundColor,
          color,
          fontFamily,
        }}>
        {[
          { key: 'headerIcon', style: headerIcon.style, isIcon: true },
          { key: 'schoolName', style: { marginTop: '4%', ...schoolName.style } },
          { key: 'certificationName', style: { marginTop: '3%', ...certificationName.style } },
          {
            key: 'toUser',
            style: { marginTop: '4%', ...toUser.style, noSelect: isAssigned },
            value: isAssigned && toUserName ? toUserName : '',
          },
          { key: 'description', style: { marginTop: '4%', ...description.style } },
          { key: 'activityDate', style: { marginBottom: '2%', marginTop: '3%', ...activityDate.style }, isDate: true },
          {
            key: '',
            style: {
              marginTop: '15%',
              borderBottom: '1px solid #bbbbbb',
              noActive: true,
            },
          },
          { key: 'fromUser', style: { marginTop: '2%', ...fromUser.style } },
          { key: 'fromUserDesignation', style: { marginTop: '1%', ...fromUserDesignation.style } },
        ].map((el, i) => {
          const fieldText =
            el?.key === 'activityDate'
              ? moment(appreciation?.[el.key]?.fieldValue).format('MMM YYYY')
              : el?.value
              ? el?.value
              : el.isDirect
              ? appreciation?.[el.key]
              : appreciation?.[el?.key]?.fieldValue;
          const itemStyle = el.style;
          return el.isIcon ? (
            <div
              key={i}
              className="text-center"
              style={{
                ...(!el?.style?.noActive &&
                  [activeField, selectedField].includes(el?.key) && {
                    borderTop: activeBorder,
                    borderBottom: activeBorder,
                  }),
              }}
              onMouseEnter={() => setActiveFieldChange(el?.key)}
              onMouseLeave={() => setActiveFieldChange('')}
              onClick={() => handleSelectItemChange(el?.key)}>
              <i
                className={fieldText}
                aria-hidden="true"
                style={{
                  ...(itemStyle?.fontSize && { fontSize: Number(itemStyle?.fontSize) }),
                  color: itemStyle.color,
                }}
              />
            </div>
          ) : !el?.style?.noActive ? (
            <div
              key={i}
              style={{
                ...(!el?.style?.noSelect &&
                  [activeField, selectedField].includes(el?.key) && {
                    borderTop: activeBorder,
                    borderBottom: activeBorder,
                  }),
                textAlign: 'center',
                marginTop: itemStyle?.marginTop,
                ...(itemStyle?.marginBottom && { marginBottom: itemStyle?.marginBottom }),
                ...(itemStyle?.fontSize && { fontSize: Number(itemStyle?.fontSize) }),
                ...(itemStyle?.fontFamily && { fontFamily: itemStyle?.fontFamily }),
                color: itemStyle?.color,
                fontWeight: itemStyle?.fontWeight,
                ...(itemStyle.borderBottom && { borderBottom: itemStyle.borderBottom }),
                ...(itemStyle.width && { width: itemStyle.width }),
              }}
              onMouseEnter={() => setActiveFieldChange(el?.key)}
              onMouseLeave={() => setActiveFieldChange('')}
              onClick={() => handleSelectItemChange(el?.key)}>
              {itemStyle.isCaps ? fieldText?.toUpperCase() : fieldText}
            </div>
          ) : (
            <div
              key={i}
              style={{
                marginTop: itemStyle?.marginTop,
                textAlign: 'center',
              }}>
              <div
                style={{
                  textAlign: 'center',
                  ...(itemStyle.borderBottom && { borderBottom: itemStyle.borderBottom }),
                  ...(itemStyle.height && { width: itemStyle.height }),
                  marginRight: '25%',
                  marginLeft: '25%',
                }}
              />
            </div>
          );
        })}
      </CardContent>
    </Card>
  );
};

export default AwardCard;
