import React from 'react';
import { Label } from 'reactstrap';

function ColorPicker({ label, name, value, handleColorChange, disabled }) {
  return (
    <>
      <Label>{label}</Label>
      <div>
        <input
          style={{ width: '100%' }}
          name={name}
          type="color"
          value={value}
          onChange={e => {
            handleColorChange(e.target.name, e.target.value);
          }}
          disabled={disabled}
        />
      </div>
    </>
  );
}

export default ColorPicker;
